test('addLine preserves voucher on draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
